//! and the devices paired with it (`devices.json`). Both are small files
//! beside `views.json`, written through the store's atomic path. The
//! certificate's private key is not here: it is a Keychain item under
//! [`Identity::key_account`].

use std::time::SystemTime;

use serde::{Deserialize, Serialize};
use uuid::Uuid;

/// The file names inside the data directory.
pub const IDENTITY_FILE: &str = "identity.json";
pub const DEVICES_FILE: &str = "devices.json";

/// The version of `identity.json` this build writes.
pub const IDENTITY_SCHEMA_VERSION: u32 = 1;

/// The port the host listens on unless the identity says otherwise.
pub const DEFAULT_REMOTE_PORT: u16 = 43187;

/// Who this installation is to a remote client, and how it listens.
/// Made once on first start and kept for the life of the data
/// directory; a second data directory has its own.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct Identity {
    pub schema_version: u32,
    /// Stable, random; never derived from the hostname or an address.
    pub server_id: Uuid,
    /// The display name a client shows for this host.
    pub server_name: String,
    /// The self-signed certificate, DER, base64. Public.
    pub certificate: String,
    /// SHA-256 over the certificate's `SubjectPublicKeyInfo`, hex: what
    /// a client pins, so a certificate reissued over the same key still
    /// verifies.
    pub spki_sha256: String,
    pub created: SystemTime,
    /// How the port binds.
    #[serde(default)]
    pub listen: Listen,
}

impl Identity {
    /// The Keychain account the certificate's private key is filed
    /// under: one per installation, so two data directories under one
    /// macOS account never overwrite each other's keys.
    #[must_use]
    pub fn key_account(&self) -> String {
        format!("remote-key:{}", self.server_id)
    }
}

/// Where the remote port binds. Loopback only until the owner allows
/// devices on the local network.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct Listen {
    /// Bind every interface rather than loopback alone.
    pub lan: bool,
    pub port: u16,
}

impl Default for Listen {
    fn default() -> Self {
        Self {
            lan: false,
            port: DEFAULT_REMOTE_PORT,
        }
    }
}

/// What a paired device may do. Set in the host's dialog, never over
/// the port.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "lowercase")]
pub enum Scope {
    /// Every view and content read.
    Read,
    /// Reads, and the commands that put text into a session.
    Control,
}

impl Scope {
    #[must_use]
    pub fn word(self) -> &'static str {
        match self {
            Self::Read => "read",
            Self::Control => "control",
        }
    }
}

/// One device the owner paired. The bearer token itself is never
/// stored: its SHA-256 is what a request's token is checked against.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct PairedDevice {
    pub id: Uuid,
    /// What the device called itself when it paired.
    pub name: String,
    pub scope: Scope,
    /// SHA-256 of the bearer token, hex.
    pub token_sha256: String,
    pub created: SystemTime,
    /// When the device last made an authenticated request.
    #[serde(default)]
    pub last_seen: Option<SystemTime>,
}

/// The two files on disk. A missing file reads as absent or empty; a
/// malformed one is an error the app reports rather than overwrites.
pub trait RemoteStore: Send {
    fn load_identity(&self) -> Result<Option<Identity>, String>;
    fn save_identity(&self, identity: &Identity) -> Result<(), String>;
    fn load_devices(&self) -> Result<Vec<PairedDevice>, String>;
    fn save_devices(&self, devices: &[PairedDevice]) -> Result<(), String>;
}

/// What the host advertises over Bonjour while it listens on the local
/// network: `_switchboard._tcp` under an instance name, with TXT records
/// a client can match against a known server before it connects. Never
/// a token, never key material: the key hash is read from `/info` over
/// the pinned connection, not from a multicast record anyone can send.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Advertisement {
    /// The Bonjour instance name: the display name with a short id
    /// suffix, so two installations on one machine stay distinct.
    pub instance: String,
    pub server_id: Uuid,
    pub server_name: String,
    pub port: u16,
}

impl Advertisement {
    /// The service type, as the client browses for it.
    pub const SERVICE: &'static str = "_switchboard._tcp";
    /// The protocol major version in the `v` TXT record.
    pub const PROTOCOL: &'static str = "1";

    #[must_use]
    pub fn new(server_id: Uuid, server_name: &str, port: u16) -> Self {
        let short = &server_id.simple().to_string()[..6];
        Self {
            instance: format!("{server_name} ({short})"),
            server_id,
            server_name: server_name.to_owned(),
            port,
        }
    }

    /// The TXT records, in the order they are published.
    #[must_use]
    pub fn txt(&self) -> Vec<(String, String)> {
        vec![
            ("v".into(), Self::PROTOCOL.into()),
            ("name".into(), self.server_name.clone()),
            ("id".into(), self.server_id.to_string()),
        ]
    }
}

/// Bonjour as the host uses it: one advertisement at a time, replaced by
/// the next `advertise` and withdrawn when the port leaves the LAN.
pub trait Advertiser: Send {
    fn advertise(&mut self, ad: &Advertisement) -> Result<(), String>;
    fn withdraw(&mut self);
}
//! The remote port's state: the host's identity, the devices paired
//! with it, and the pairing window. Random material (the code, a
//! token) is made outside and arrives in the action; here it is only
//! compared and kept, so every transition is a plain function of its
//! inputs.

use std::time::SystemTime;

use uuid::Uuid;

use super::action::PairingWindow;
use super::action::{AppAction, AppCore, Clock, Effect, Out, PAIRING_ATTEMPTS, PAIRING_WINDOW};
use crate::ports::remote::{Identity, PairedDevice, Scope};

/// A device's last-seen time is saved when it moved by at least this
/// much, so a polling device does not rewrite `devices.json` on every
/// request.
const LAST_SEEN_SAVE_INTERVAL_SECS: u64 = 300;

impl AppCore {
    pub(super) fn remote_action(&mut self, action: AppAction, now: Clock, out: &mut Out) {
        match action {
            AppAction::IdentityLoaded {
                identity,
                devices,
                rotated,
            } => {
                self.identity = Some(identity);
                self.devices = devices;
                self.identity_rotated_at = rotated.then_some(now.mono);
            }
            AppAction::SetServerName(name) => {
                let name = name.trim().to_owned();
                if !name.is_empty() {
                    self.update_identity(out, |i| i.server_name = name);
                }
            }
            AppAction::SetRemoteListen { lan, port } => {
                if port != 0 {
                    self.update_identity(out, |i| {
                        i.listen.lan = lan;
                        i.listen.port = port;
                    });
                }
            }
            AppAction::OpenPairing { code, scope } => {
                // Typed by hand on the device, so case never matters.
                self.pairing = Some(PairingWindow {
                    until: now.mono + PAIRING_WINDOW,
                    code: code.trim().to_ascii_uppercase(),
                    scope,
                    failures: 0,
                });
            }
            AppAction::ClosePairing => self.pairing = None,
            AppAction::PairingFailed => {
                if let Some(p) = &mut self.pairing {
                    p.failures += 1;
                    if p.failures >= PAIRING_ATTEMPTS {
                        self.pairing = None;
                        self.error("Pairing closed: three attempts failed.");
                    }
                }
            }
            AppAction::Paired(device) => {
                // The code is single-use: the window closes with the
                // first pairing made through it.
                self.pairing = None;
                self.devices.push(device);
                self.save_devices(out);
            }
            AppAction::DeviceSeen(id) => {
                let Some(device) = self.devices.iter_mut().find(|d| d.id == id) else {
                    return;
                };
                let stale = device.last_seen.is_none_or(|seen| {
                    now.wall
                        .duration_since(seen)
                        .is_ok_and(|d| d.as_secs() >= LAST_SEEN_SAVE_INTERVAL_SECS)
                });
                device.last_seen = Some(now.wall);
                if stale {
                    self.save_devices(out);
                }
            }
            AppAction::RevokeDevice(id) => {
                let before = self.devices.len();
                self.devices.retain(|d| d.id != id);
                if self.devices.len() != before {
                    self.save_devices(out);
                }
            }
            AppAction::SetDeviceScope { device, scope } => {
                if let Some(d) = self.devices.iter_mut().find(|d| d.id == device)
                    && d.scope != scope
                {
                    d.scope = scope;
                    self.save_devices(out);
                }
            }
            _ => unreachable!("dispatched by `dispatch` itself"),
        }
    }

    fn update_identity(&mut self, out: &mut Out, change: impl FnOnce(&mut Identity)) {
        let Some(identity) = &self.identity else {
            return;
        };
        let mut next = identity.clone();
        change(&mut next);
        if Some(&next) != self.identity.as_ref() {
            self.identity = Some(next.clone());
            if !self.read_only {
                out.push(Effect::SaveIdentity(next));
            }
        }
    }

    fn save_devices(&self, out: &mut Out) {
        if !self.read_only {
            out.push(Effect::SaveDevices(self.devices.clone()));
        }
    }

    /// The host's identity, once loaded.
    #[must_use]
    pub fn identity(&self) -> Option<&Identity> {
        self.identity.as_ref()
    }

    /// The key was remade at this launch: every earlier pairing is gone.
    #[must_use]
    pub fn identity_rotated(&self) -> bool {
        self.identity_rotated_at.is_some()
    }

    /// The devices paired with this host.
    #[must_use]
    pub fn devices(&self) -> &[PairedDevice] {
        &self.devices
    }

    /// The device holding the token with this hash.
    #[must_use]
    pub fn device_by_token(&self, token_sha256: &str) -> Option<&PairedDevice> {
        self.devices.iter().find(|d| d.token_sha256 == token_sha256)
    }

    /// The pairing window, while it is open at `now`. `Tick` clears a
    /// passed one; between ticks this checks the time itself.
    #[must_use]
    pub fn pairing_at(&self, now: Clock) -> Option<&PairingWindow> {
        self.pairing.as_ref().filter(|p| p.until > now.mono)
    }

    /// The pairing window as last set, passed or not; the dialog uses
    /// `pairing_at` and this is for tests.
    #[must_use]
    pub fn pairing(&self) -> Option<&PairingWindow> {
        self.pairing.as_ref()
    }

    /// A device record for a pairing that matched: the window's scope,
    /// the token's hash, and the time.
    #[must_use]
    pub fn new_device(&self, name: &str, token_sha256: String, at: SystemTime) -> PairedDevice {
        PairedDevice {
            id: Uuid::new_v4(),
            name: name.trim().chars().take(64).collect(),
            scope: self.pairing.as_ref().map_or(Scope::Read, |p| p.scope),
            token_sha256,
            created: at,
            last_seen: None,
        }
    }
}

