        let incoming: Vec<Incoming> = self
            .control
            .as_mut()
            .map(ControlSocket::poll)
            .unwrap_or_default();
        for Incoming { request, reply } in incoming {
            let answer = self.serve(&request);
            let _ = reply.send(answer);
