/// The name a new identity starts with: the machine's short host name,
/// or "Switchboard" when it has none.
#[must_use]
pub fn default_server_name() -> String {
    std::process::Command::new("hostname")
        .arg("-s")
        .output()
        .ok()
        .and_then(|o| String::from_utf8(o.stdout).ok())
        .map(|s| s.trim().to_owned())
        .filter(|s| !s.is_empty())
        .unwrap_or_else(|| "Switchboard".into())
}

// --- random material

/// The pairing code's alphabet: Crockford's base 32, with no I, L, O
/// or U, so a code read aloud or typed is never ambiguous.
        }
    }
}

#[cfg(target_os = "macos")]
impl Advertiser for Bonjour {
    fn advertise(&mut self, ad: &Advertisement) -> Result<(), String> {
        self.unregister();
        if self.daemon.is_none() {
            self.daemon = Some(mdns_sd::ServiceDaemon::new().map_err(|e| e.to_string())?);
        }
        let host = format!("{}.local.", super::remote::default_server_name());
        let txt: Vec<(String, String)> = ad.txt();
        let info = mdns_sd::ServiceInfo::new(
            &Self::service_type(),
            &ad.instance,
            &host,
            "",
            ad.port,
            &txt[..],
        )
